          <table part="data-table">
            <caption>Gantt chart tasks</caption>
            <thead><tr><th>Task</th><th>Start</th><th>End</th><th>% Complete</th><th>Status</th></tr></thead>
            <tbody class="table-body"></tbody>
          </table>
